"""Convert the user's four approved action illustrations to fixed flash icons."""
from pathlib import Path
from PIL import Image

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "assets_local/quest/redesign/action-icons"
NAMES = ("campaign", "missions", "equipment", "shop")
MISSIONS = ROOT / "assets_local/quest/redesign/mission-icons"
PHASES = ROOT / "assets_local/quest/redesign/phase-icons"


def build():
    lines = ["#pragma once", "#include <Icon.h>",
             "// Generated by tools_local/quest/build_action_icons.py from the approved reference.",
             "namespace questaction {"]
    specs = [(name, SOURCE, 96, 72, 90, 60) for name in NAMES]
    specs += [(name + "Mission", MISSIONS, 64, 64, 56, 56) for name in ("daily", "weekly", "story")]
    specs += [("phase" + str(n), PHASES, 64, 64, 56, 56) for n in range(6)]
    specs += [(name, PHASES, 64, 64, 56, 56) for name in ("pathTab", "sagaTab")]
    total = 0
    for name, source, width, height, max_width, max_height in specs:
        filename = name.removesuffix("Mission")
        image = Image.open(source / (filename + "-source.png")).convert("L")
        scale = min(max_width / image.width, max_height / image.height)
        image = image.resize((round(image.width * scale), round(image.height * scale)), Image.Resampling.LANCZOS)
        canvas = Image.new("L", (width, height), 255)
        canvas.paste(image, ((width - image.width) // 2, (height - image.height) // 2))
        icon = canvas.point(lambda px: 255 if px >= 160 else 0, "1")
        icon.save(source / (filename + ".png"))
        data = icon.tobytes()
        assert len(data) == (width // 8) * height
        total += len(data)
        lines.append(f"inline constexpr uint8_t {name}Bits[] = {{")
        for at in range(0, len(data), 20):
            lines.append("    " + ", ".join(f"0x{byte:02x}" for byte in data[at:at + 20]) + ",")
        lines.append("};")
        lines.append(f"inline constexpr freeink::Icon {name} = {{{width}, {height}, {height // 2}, {name}Bits}};")
    lines.append("}  // namespace questaction")
    (ROOT / "src/apps_local/quest/QuestActionIcons.h").write_text("\n".join(lines) + "\n", "utf-8")
    print(f"Quest illustrations: {len(specs)} approved icons, {total:,} bytes in flash; no SD or heap allocation")


if __name__ == "__main__":
    build()
